        q.add(new PracticeQuestionBank.Question("X123", "E", "Refer to Figure FA-4. What is the purpose of the fire alarm interface to an elevator controller?", "Directly power the elevator motor", "Provide a recall/homing command to the elevator control system when required", "Increase elevator speed during an alarm", "Bypass elevator safety devices", "B", "The fire alarm provides an interface signal to the elevator system; the elevator controller then performs its programmed recall/homing sequence. Basis: RSOS E-26.01 associated systems: elevator homing contactors.", "RSOS E-26.01 associated systems: elevator homing contactors."));
